    "id": "semana",
    "titulo": "3 reels a la semana desde el 15 de noviembre",
    "html": "<section id=\"semana\" data-transition=\"fade\" style=\"background:#FAF6EE;color:#211714;font-family:Figtree, Arial, sans-serif;padding:128px 128px 160px;display:flex;flex-direction:column;gap:40px\">\n<div style=\"display:flex;flex-direction:column;gap:20px\">\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:600;font-size:24px;line-height:1.2;letter-spacing:3px;text-transform:uppercase;color:#6B5F58\">Calendario</p>\n<h2 style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:72px;line-height:1.05;letter-spacing:-2px\">3 reels a la semana desde el 15 de noviembre</h2>\n</div>\n<div style=\"display:grid;grid-template-columns:repeat(7, 1fr);grid-template-rows:auto 400px;gap:16px\">\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center;color:#8A7F79\">LUN</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center;color:#8A7F79\">MAR</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center\">MIÉ</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center;color:#8A7F79\">JUE</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center\">VIE</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center;color:#8A7F79\">SÁB</p>\n<p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.2;letter-spacing:2px;text-align:center\">DOM</p>\n<div style=\"border:3px dashed #D3D1D0;border-radius:24px\"></div>\n<div style=\"border:3px dashed #D3D1D0;border-radius:24px\"></div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#ABC7FF;padding:24px 20px;border-radius:24px\"><p style=\"font-family:'Gochi Hand', 'Brush Script MT', cursive;font-size:28px;line-height:1.1;text-transform:uppercase\">Educa</p><p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.15\">Reel educativo</p><p style=\"font-size:24px;line-height:1.3\">Etiquetas, mitos y comparativas</p></div>\n<div style=\"border:3px dashed #D3D1D0;border-radius:24px\"></div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#FFC184;padding:24px 20px;border-radius:24px\"><p style=\"font-family:'Gochi Hand', 'Brush Script MT', cursive;font-size:28px;line-height:1.1;text-transform:uppercase\">Producto</p><p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.15\">Reel de producto</p><p style=\"font-size:24px;line-height:1.3\">Un snack, un beneficio</p></div>\n<div style=\"border:3px dashed #D3D1D0;border-radius:24px\"></div>\n<div style=\"display:flex;flex-direction:column;gap:12px;background:#C5F1AB;padding:24px 20px;border-radius:24px\"><p style=\"font-family:'Gochi Hand', 'Brush Script MT', cursive;font-size:28px;line-height:1.1;text-transform:uppercase\">Comunidad / humor</p><p style=\"font-family:Inter, Arial, sans-serif;font-weight:800;font-size:28px;line-height:1.15\">Reel de comunidad</p><p style=\"font-size:24px;line-height:1.3\">UGC, reacciones y memes, alternos</p></div>\n</div>\n<div style=\"display:flex;flex-direction:row;gap:14px;align-items:center;flex-wrap:wrap\">\n<p style=\"font-family:'Titan One', 'Arial Black', sans-serif;font-size:30px;line-height:1.2;background:#211714;color:#FCDC8D;padding:12px 26px;border-radius:999px\">7 REELS EN NOVIEMBRE</p>\n<p style=\"font-size:26px;line-height:1.2;background:#FFFFFF;padding:12px 24px;border-radius:999px;border:2px solid #211714\">Gancho en los 3 primeros segundos</p>\n<p style=\"font-size:26px;line-height:1.2;background:#FFFFFF;padding:12px 24px;border-radius:999px;border:2px solid #211714\">Subtítulos siempre</p>\n<p style=\"font-size:26px;line-height:1.2;background:#FFFFFF;padding:12px 24px;border-radius:999px;border:2px solid #211714\">Llamada a la acción a barkita.com</p>\n</div>\n<img src=\"/pitch/barkita/logo-h-cacao.png\" alt=\"Barkita\" style=\"position:absolute;left:128px;bottom:66px;width:150px;height:24px;object-fit:contain\">\n<p style=\"position:absolute;left:300px;bottom:62px;width:900px;font-size:24px;line-height:1.2;color:#6B5F58\">Briefing estratégico · Maen Studios × Barkita</p>\n<p style=\"position:absolute;right:128px;bottom:62px;width:120px;text-align:right;font-family:Inter, Arial, sans-serif;font-weight:700;font-size:24px;line-height:1.2\">17</p>\n</section>"
