    "id": "cierre",
    "titulo": "¿Empezamos?",
    "html": "<section id=\"cierre\" data-transition=\"fade\" style=\"background:#FCDC8D;color:#211714;font-family:Figtree, Arial, sans-serif;padding:128px;display:flex;flex-direction:column\">\n<img src=\"/pitch/barkita/logo-h-hueso.png\" alt=\"Logotipo de Barkita en grande\" style=\"position:absolute;left:128px;top:660px;width:1664px;height:270px;object-fit:contain\">\n<h1 style=\"position:absolute;left:128px;top:150px;width:1100px;font-family:Inter, Arial, sans-serif;font-weight:800;font-size:160px;line-height:1;letter-spacing:-6px\">¿Empezamos?</h1>\n<p style=\"position:absolute;left:128px;top:360px;width:900px;font-size:36px;line-height:1.4\">Cualquier duda, aquí estamos.<br>Maen Studios · Madrid</p>\n<img src=\"/pitch/barkita/cut-142.png\" alt=\"Bolsa de nervio de toro\" data-build-in=\"pop 1\" style=\"position:absolute;left:1360px;top:110px;width:420px;height:418px;object-fit:contain;transform:rotate(8deg)\">\n<p data-build-in=\"rise 2\" style=\"position:absolute;left:1180px;top:480px;width:440px;font-family:'Gochi Hand', 'Brush Script MT', cursive;font-size:40px;line-height:1.1;text-transform:uppercase;text-align:center;background:#FAF6EE;padding:12px 22px;border-radius:999px;transform:rotate(-5deg);white-space:nowrap\">¡Nos vemos en el feed!</p>\n</section>"
